    rows = ''
    for i, c in enumerate(records, 1):
        bg = '#fde8e8' if highlight == 'high' else '#e8f8e8'
        rows += f'''<tr style="background:{bg if i <= 3 else 'white'}">
            <td>{i}</td>
            <td>{c['country']}</td>
            <td>{c['year']}</td>
            <td style="font-weight:600">{fmt_rate(c['homicide_rate'])}</td>
        </tr>'''
    return rows

# Notable trends table
def trends_table(records, direction='improvement'):
    rows = ''
    for i, c in enumerate(records, 1):
        bg = '#e8f8e8' if direction == 'improvement' else '#fde8e8'
        arrow = '↓' if direction == 'improvement' else '↑'
        rows += f'''<tr style="background:{bg if i <= 3 else 'white'}">
            <td>{i}</td>
            <td>{c['country']}</td>
            <td>{fmt_rate(c['early_rate'])}</td>
            <td>{fmt_rate(c['late_rate'])}</td>
            <td style="font-weight:600">{arrow} {abs(c['pct_change']):.1f}%</td>
