    return rows

# Notable trends table
def trends_table(records, direction='improvement'):
    rows = ''
    for i, c in enumerate(records, 1):
        bg = '#e8f8e8' if direction == 'improvement' else '#fde8e8'
        arrow = '↓' if direction == 'improvement' else '↑'
        rows += f'''<tr style="background:{bg if i <= 3 else 'white'}">
