def b64_img(b64_str):
    return f'<img src="data:image/png;base64,{b64_str}" style="max-width:100%; height:auto;" />'

# Format numbers
def fmt_rate(v):
    return f'{v:.2f}'

def fmt_pct(v):
    return f'{v:+.1f}%'

# Build top/bottom 10 tables
def country_table(records, highlight='high'):
    rows = ''
    for i, c in enumerate(records, 1):
        bg = '#fde8e8' if highlight == 'high' else '#e8f8e8'
        rows += f'''<tr style="background:{bg if i <= 3 else 'white'}">
            <td>{i}</td>
            <td>{c['country']}</td>
            <td>{c['year']}</td>
            <td style="font-weight:600">{fmt_rate(c['homicide_rate'])}</td>
        </tr>'''
    return rows

# Notable trends table
def trends_table(records, direction='improvement'):
    rows = ''
    for i, c in enumerate(records, 1):
        bg = '#e8f8e8' if direction == 'improvement' else '#fde8e8'
        arrow = '↓' if direction == 'improvement' else '↑'
        rows += f'''<tr style="background:{bg if i <= 3 else 'white'}">
            <td>{i}</td>
            <td>{c['country']}</td>
            <td>{fmt_rate(c['early_rate'])}</td>
            <td>{fmt_rate(c['late_rate'])}</td>
            <td style="font-weight:600">{arrow} {abs(c['pct_change']):.1f}%</td>
        </tr>'''
    return rows

# Top M/F ratio table
def mf_table(records):
    rows = ''
    for i, c in enumerate(records, 1):
        rows += f'''<tr>
            <td>{i}</td>
            <td>{c['iso_code']}</td>
            <td>{fmt_rate(c['male_rate'])}</td>
            <td>{fmt_rate(c['female_rate'])}</td>
            <td style="font-weight:600">{fmt_rate(c['ratio'])}:1</td>
